  await pg.goto('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas&atnaujinti=1&q=girkles+nagams&per=20',{waitUntil:'domcontentloaded',timeout:150000}).catch(()=>{});
  await pg.goto('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas&atnaujinti=1&q=nagams&per=20',{waitUntil:'domcontentloaded',timeout:150000});
  await pg.waitForTimeout(2500);
  out.rasta=await pg.evaluate(()=>Array.from(document.querySelectorAll(".pskat-t tbody tr[data-id]")).map(t=>t.dataset.id));
